$calculations$::jsonb);

  -- Null source URLs identify the original autogenerated rules. A same-day merge
  -- may already have inherited astronomy's URL; its matching provenance proves it
  -- is the same autogenerated occurrence. Explicit curated sources are preserved.
  create temp table _astronomy_legacy on commit drop as
    select e.id, e.slug, e.featured, e.popularity, c.source_key, c.series_slug
    from public.events e join _astronomy_calculations c
      on e.series_slug=c.series_slug and extract(year from e.starts_on)=c.year
    join public.series s on s.slug=c.series_slug
    where e.published and e.status not in ('done','cancelled','retired')
      and e.source='curated' and e.category='astronomy' and e.title=s.title
      and e.source_key ~ ('^curated:' || c.series_slug || '-[0-9]{4}-[0-9]{2}-[0-9]{2}$')
      and (e.source_url is null or exists (
        select 1 from public.event_sources es where es.event_id=e.id and es.source_key=c.source_key and es.source='astronomy'));

  create temp table _astronomy_targets on commit drop as
    select c.*, coalesce(
      (select e.id from public.events e where e.source_key=c.source_key and e.source='astronomy'
        and e.published and e.status not in ('done','cancelled','retired')),
      (select e.id from public.event_sources es join public.events e on e.id=es.event_id
        where es.source_key=c.source_key and es.source='astronomy'
          and e.published and e.status not in ('done','cancelled','retired')
          and (e.source='astronomy' or exists(select 1 from _astronomy_legacy l where l.id=e.id))),
      (select l.id from _astronomy_legacy l where l.source_key=c.source_key order by l.id limit 1)) as target_id
    from _astronomy_calculations c;
  delete from _astronomy_targets where target_id is null;

  -- Do not take a slug belonging to a separately reviewed event.
  delete from _astronomy_targets t where exists (
    select 1 from public.events e where e.slug=t.slug and e.id<>t.target_id
      and not exists(select 1 from _astronomy_legacy l where l.id=e.id and l.source_key=t.source_key));

  insert into public.event_slugs(slug,event_id)
    select l.slug,t.target_id from _astronomy_legacy l join _astronomy_targets t using(source_key)
    where l.id<>t.target_id
    on conflict(slug) do update set event_id=excluded.event_id;
  update public.event_slugs a set event_id=t.target_id
    from _astronomy_legacy l join _astronomy_targets t using(source_key)
    where a.event_id=l.id and l.id<>t.target_id;
  update public.event_sources es set event_id=t.target_id
    from _astronomy_legacy l join _astronomy_targets t using(source_key)
    where es.event_id=l.id and l.id<>t.target_id;

  -- Release duplicate slugs before correcting the winning row; aliases retain URLs.
  update public.events e set published=false,status='retired',featured=false,indexable=false,
    slug='retired-astronomy-' || substr(md5(e.id),1,12) || '-' || e.starts_on::text
    from _astronomy_legacy l join _astronomy_targets t using(source_key)
    where e.id=l.id and l.id<>t.target_id;

  update public.events e set source='astronomy',source_key=t.source_key,series_slug=t.series_slug,
    confidence=(t.payload->>'confidence')::numeric,timezone=t.payload->>'timezone',
    featured=e.featured or coalesce((select bool_or(l.featured) from _astronomy_legacy l where l.source_key=t.source_key),false),
    popularity=greatest(e.popularity,coalesce((select max(l.popularity) from _astronomy_legacy l where l.source_key=t.source_key),0))
    from _astronomy_targets t where e.id=t.target_id;

  -- A previous lower-rank merge can already have this content hash in provenance.
  -- Force a real update so ownership changes cannot leave day precision behind.
  update public.event_sources es set content_hash=repeat('0',64)
    from _astronomy_targets t where es.source_key=t.source_key;
  if exists(select 1 from _astronomy_targets) then
    perform public.upsert_events((select jsonb_agg(payload) from _astronomy_targets));
  end if;
end $correction$;
